# -*- coding: utf-8 -*-
"""Parse the creative dictionary site into a word graph + 3D layout.

Canonical word name comes from each page's <h1> (filenames on disk are
mojibake; HTML hrefs are properly percent-encoded). Pages with a
< meta refresh > are redirect stubs, not words: links to them follow the
redirect one level. Relations are the links inside a page's
< section > (sinonimos / analogas); the aside and footer are navigation.
"""
import json, math, os, re, html
from urllib.parse import unquote

ROOT = os.path.dirname(os.path.abspath(__file__))
SITE = os.path.join(ROOT, "site")
SKIP = {"index.html", "sobre.html", "contato.html"}

def read(p):
    for enc in ("utf-8", "utf-8-sig", "latin-1"):
        try:
            return open(p, encoding=enc).read()
        except UnicodeDecodeError:
            continue
    raise ValueError("undecodable: " + p)

def norm(s):
    return s.strip().lower()

pages = {}
for fn in sorted(os.listdir(SITE)):
    if not fn.lower().endswith(".html") or fn in SKIP:
        continue
    pages[fn] = read(os.path.join(SITE, fn))

def norm_noaccent(s):
    import unicodedata
    d = unicodedata.normalize("NFD", s)
    return "".join(c for c in d if unicodedata.category(c) != "Mn")

# classify pages
redirects = {}   # stem -> target stem (meta refresh)
entries = {}     # word (h1) -> {tema, stem, text}
for fn, text in pages.items():
    m = re.search(r'<meta http-equiv="refresh" content="\d+;\s*url=([^">]+)"', text)
    if m:
        redirects[norm(unquote(os.path.splitext(fn)[0]))] = norm(unquote(os.path.splitext(m.group(1))[0]))
        continue
    hm = re.search(r"<h1>(.*?)</h1>", text)
    word = html.unescape(hm.group(1)).strip() if hm else norm(unquote(os.path.splitext(fn)[0]))
    tm = re.search(r'<p class="tema">Tema:\s*([^<]+)</p>', text)
    tema = tm.group(1).strip() if tm else ""
    entries[word] = {"tema": tema, "stem": norm(unquote(os.path.splitext(fn)[0])), "text": text}

# lookup: word by h1 (accented, from content) and by raw stem (mojibake-safe)
key2word = {}
for w, d in entries.items():
    key2word[norm(w)] = w
    key2word[d["stem"]] = w

def stem_of(href):
    return norm(unquote(os.path.splitext(href)[0]))

def resolve(href):
    """Canonical word an href points to, following one redirect. None if unknown."""
    if href in SKIP or not href.lower().endswith(".html"):
        return None
    k = stem_of(href)
    if k in redirects:
        k = redirects[k]
    return key2word.get(k)

link_re = re.compile(r"<section id=\"([^\"]+)\">(.*?)</section>", re.S)
a_re = re.compile(r"<a href=\"([^\"]+)\">([^<]*)</a>")

graph = {}
ghosts = {}
for w, d in entries.items():
    g = graph.setdefault(w, {"sinonimos": set(), "analogas": set()})
    for sid, body in link_re.findall(d["text"]):
        for href, label in a_re.findall(body):
            tgt = resolve(href)
            if tgt is None:
                gg = ghosts.setdefault(stem_of(href), {"label": label, "from": set()})
                gg["from"].add(w)
                continue
            g["sinonimos" if sid == "sinonimos" else "analogas"].add(tgt)

for g in ghosts.values():
    g["from"] = sorted(set(g["from"]))

words = {}
for w in sorted(entries, key=norm):
    g = graph[w]
    linked = list(g["sinonimos"]) + [x for x in g["analogas"] if x not in g["sinonimos"]]
    words[w] = sorted(set(linked), key=norm)

# ---- stats
degree = {}
pairs = set()
for w, ls in words.items():
    for t in ls:
        a, b = tuple(sorted([norm(w), norm(t)]))
        pairs.add((a, b))
        degree[a] = degree.get(a, 0) + 1
        degree[b] = degree.get(b, 0) + 1
best_key = max(degree, key=lambda k: (degree[k], k))
best_word = next(w for w in words if norm(w) == best_key)
result = {
